import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
import { mkdirSync, writeFileSync } from 'fs';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';

const SCENE_PATH = '/root/data/object.js';
const OUTPUT_ROOT = '/root/output';
const PART_DIR = path.join(OUTPUT_ROOT, 'part_meshes');
const LINK_DIR = path.join(OUTPUT_ROOT, 'links');

function sanitize(name) {
  const cleaned = (name || 'unnamed')
    .replace(/[^a-zA-Z0-9_-]+/g, '_')
    .replace(/^_+|_+$/g, '');
  return cleaned || 'unnamed';
}

function uniqueName(base, used) {
  let name = base;
  let i = 1;
  while (used.has(name)) {
    name = `${base}_${i}`;
    i += 1;
  }
  used.add(name);
  return name;
}

function exportMeshLocal(mesh, exporter) {
  const clone = mesh.clone();
  clone.updateMatrixWorld(true);
  return exporter.parse(clone);
}

function exportGroupLocal(group, exporter) {
  const clone = group.clone(true);
  clone.position.set(0, 0, 0);
  clone.rotation.set(0, 0, 0);
  clone.scale.set(1, 1, 1);
  clone.updateMatrixWorld(true);
  return exporter.parse(clone);
}

async function main() {
  const sceneModule = await import(pathToFileURL(SCENE_PATH));
  if (!sceneModule.createScene) {
    throw new Error('createScene() not found in object.js');
  }

  const root = sceneModule.createScene();
  root.updateMatrixWorld(true);

  mkdirSync(PART_DIR, { recursive: true });
  mkdirSync(LINK_DIR, { recursive: true });

  const exporter = new OBJExporter();

  const groups = [];
  root.traverse((obj) => {
    if (obj.isGroup) groups.push(obj);
  });

  const usedPartNames = new Set();

  for (const group of groups) {
    const partBase = sanitize(group.name || 'group');
    const partName = uniqueName(partBase, usedPartNames);

    const directMeshes = group.children.filter((child) => child.isMesh);

    if (directMeshes.length > 0) {
      const partPath = path.join(PART_DIR, partName);
      mkdirSync(partPath, { recursive: true });

      const usedMeshNames = new Set();
      for (const mesh of directMeshes) {
        const meshBase = sanitize(mesh.name || 'mesh');
        const meshName = uniqueName(meshBase, usedMeshNames);
        const objText = exportMeshLocal(mesh, exporter);
        const outPath = path.join(partPath, `${meshName}.obj`);
        writeFileSync(outPath, objText, 'utf8');
      }
    }

    // Only export a link if the group contains any meshes in its subtree.
    let hasMesh = false;
    group.traverse((obj) => {
      if (obj.isMesh) hasMesh = true;
    });

    if (hasMesh) {
      const linkText = exportGroupLocal(group, exporter);
      const linkPath = path.join(LINK_DIR, `${partName}.obj`);
      writeFileSync(linkPath, linkText, 'utf8');
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
